begin;
-- Recepción consulta un directorio administrativo sin notas clínicas.
create policy recepcion_perfil_privado on perfiles_pacientes as restrictive for select to authenticated using(clinica_rol() is distinct from 'recepcionista');
create policy recepcion_expediente_privado on expedientes as restrictive for select to authenticated using(clinica_rol() is distinct from 'recepcionista');
create policy recepcion_internacion_privada on internaciones as restrictive for select to authenticated using(clinica_rol() is distinct from 'recepcionista');
create policy recepcion_episodio_privado on episodios_medicos as restrictive for select to authenticated using(clinica_rol() is distinct from 'recepcionista');
create policy recepcion_orden_privada on ordenes_medicas as restrictive for select to authenticated using(clinica_rol() is distinct from 'recepcionista');
create policy recepcion_resultado_privado on solicitudes_analisis as restrictive for select to authenticated using(clinica_rol() is distinct from 'recepcionista');
create function public.clinica_recepcion_proteger() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if clinica_rol()='recepcionista' then
  if tg_table_name='perfiles_pacientes' then
   if tg_op='INSERT' and nullif(new.notas_medicas,'') is not null then raise exception 'Recepción solo registra datos administrativos' using errcode='42501'; end if;
   if tg_op='UPDATE' and (new.notas_medicas is distinct from old.notas_medicas or new.esta_activo is distinct from old.esta_activo or new.usuario_id is distinct from old.usuario_id) then raise exception 'Recepción no puede modificar información clínica ni desactivar pacientes' using errcode='42501'; end if;
  elsif tg_op='UPDATE' then
   if exists(select 1 from recepcion_llegadas l where l.cita_id=old.id and l.inicio_cita=old.inicio and l.en_consulta is not null) and new is distinct from old then raise exception 'La consulta ya comenzó. Comunícate con el médico' using errcode='42501'; end if;
   if (new.inicio,new.fin,new.medico_id,new.paciente_id) is distinct from (old.inicio,old.fin,old.medico_id,old.paciente_id) and (old.estado::text not in('pendiente','confirmada') or exists(select 1 from recepcion_llegadas l where l.cita_id=old.id and l.inicio_cita=old.inicio)) then raise exception 'No se puede reagendar una cita resuelta o con llegada registrada' using errcode='42501'; end if;
   if new.estado is distinct from old.estado then
    if new.estado::text not in('confirmada','cancelada_paciente','no_asistio') or old.estado::text not in('pendiente','confirmada') then raise exception 'Recepción no puede finalizar ni reabrir consultas' using errcode='42501'; end if;
    if new.estado::text='no_asistio' and old.fin>clock_timestamp() then raise exception 'Espera al término de la cita para registrar una inasistencia'; end if;
    if new.estado::text='no_asistio' and exists(select 1 from recepcion_llegadas l where l.cita_id=old.id and l.inicio_cita=old.inicio) then raise exception 'El paciente ya llegó a su cita'; end if;
    if new.estado::text in('cancelada_paciente','no_asistio') and length(trim(coalesce(new.motivo_cancelacion,''))) not between 1 and 1000 then raise exception 'Registra el motivo de la cancelación o inasistencia'; end if;
   end if;
  end if;
 end if;
 return new;
end $$;
create trigger recepcion_proteger_perfil before insert or update on perfiles_pacientes for each row execute function clinica_recepcion_proteger();
create trigger recepcion_proteger_cita before update on citas for each row execute function clinica_recepcion_proteger();

create function public.clinica_directorio_recepcion(p_id bigint default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
 perform clinica_requerir_sesion();
 if clinica_rol()<>'recepcionista' or clinica_rol() is null then raise exception 'Sin acceso al directorio de recepción' using errcode='42501'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'usuario_id',p.usuario_id,'esta_activo',p.esta_activo,'fecha_nacimiento',p.fecha_nacimiento,'genero',p.genero,
 'nombre_contacto_emergencia',p.nombre_contacto_emergencia,'telefono_emergencia',p.telefono_emergencia,
 'usuarios',jsonb_build_object('nombre_completo',u.nombre_completo,'correo',u.correo,'telefono',u.telefono,'esta_activo',u.esta_activo)) order by p.id)
 from perfiles_pacientes p join usuarios u on u.id=p.usuario_id where p_id is null or p.id=p_id),'[]'::jsonb);
end $$;

create table public.recepcion_llegadas (
 cita_id bigint primary key references citas(id), inicio_cita timestamptz not null,
 llegada timestamptz not null default clock_timestamp(), en_consulta timestamptz,
 autor bigint not null references usuarios(id), iniciado_por bigint references usuarios(id), clave uuid not null unique
);
create table public.recepcion_eventos (
 id bigint generated by default as identity primary key, cita_id bigint not null references citas(id), autor bigint not null references usuarios(id),
 accion text not null, motivo text, creado_en timestamptz not null default clock_timestamp(), clave uuid not null, solicitud jsonb not null,
 unique(autor,clave)
);
alter table recepcion_llegadas enable row level security;
alter table recepcion_eventos enable row level security;
create policy recepcion_llegadas_lectura on recepcion_llegadas for select to authenticated using(clinica_sesion_activa() and (clinica_rol() in('admin','recepcionista') or exists(select 1 from citas c where c.id=cita_id and (c.medico_id=clinica_medico() or clinica_rol()='enfermero' and clinica_paciente(c.paciente_id)))));
create policy recepcion_eventos_lectura on recepcion_eventos for select to authenticated using(clinica_sesion_activa() and clinica_rol()='admin');
grant select on recepcion_llegadas,recepcion_eventos to authenticated;

-- Las llegadas registradas en el turno de enfermería alimentan la misma sala.
create function public.clinica_recepcion_llegada_enfermeria() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare c citas;
begin
 if new.tipo<>'llegada' then return new; end if;
 select * into c from citas where id=(new.datos->>'citaId')::bigint and paciente_id=new.paciente_id;
 if c.id is null then raise exception 'Cita de llegada inválida'; end if;
 insert into recepcion_llegadas(cita_id,inicio_cita,llegada,autor,clave) values(c.id,c.inicio,new.creado_en,new.autor,gen_random_uuid())
  on conflict(cita_id) do update set inicio_cita=excluded.inicio_cita,llegada=excluded.llegada,autor=excluded.autor,clave=excluded.clave,en_consulta=null,iniciado_por=null
  where recepcion_llegadas.inicio_cita<>excluded.inicio_cita;
 insert into notificaciones(usuario_id,tipo,titulo,mensaje,clave)
 select u.id,'recepcion','Paciente en sala de espera','Enfermería registró una llegada para la cita #'||c.id||'. Revisa tu agenda.','llegada-enfermeria:'||new.id
 from usuarios u where u.esta_activo and (u.rol='recepcionista' or u.id=(select usuario_id from perfiles_medicos where id=c.medico_id)) on conflict do nothing;
 return new;
end $$;
create trigger recepcion_llegada_enfermeria after insert on enfermeria_registros for each row execute function clinica_recepcion_llegada_enfermeria();

-- La RPC de enfermería declara una variable «inicio». Califica la columna de
-- la cita al validar el día, conservando intactas las migraciones ya instaladas.
do $reparar$
declare original text; corregida text;
begin
 select pg_get_functiondef('public.clinica_enfermeria_operar(text,jsonb,uuid)'::regprocedure) into original;
 corregida:=replace(original,$antes$(inicio at time zone 'America/Mexico_City')::date=(clock_timestamp() at time zone 'America/Mexico_City')::date$antes$,
 $despues$(citas.inicio at time zone 'America/Mexico_City')::date=(clock_timestamp() at time zone 'America/Mexico_City')::date$despues$);
 if corregida=original then raise exception 'Revisa la definición del registro de llegadas de enfermería antes de continuar'; end if;
 execute corregida;
end $reparar$;

create function public.clinica_recepcion_panel(p_dia date default null) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare dia date:=coalesce(p_dia,(clock_timestamp() at time zone 'America/Mexico_City')::date); v_desde timestamptz; v_hasta timestamptz;
begin
 perform clinica_requerir_sesion();
 if clinica_rol() not in('admin','recepcionista') or clinica_rol() is null then raise exception 'Sin acceso a recepción' using errcode='42501'; end if;
 v_desde:=dia::timestamp at time zone 'America/Mexico_City'; v_hasta:=(dia+1)::timestamp at time zone 'America/Mexico_City';
 return jsonb_build_object('dia',dia,'ahora',clock_timestamp(),'citas',coalesce((select jsonb_agg(jsonb_build_object(
 'id',c.id,'pacienteId',p.id,'paciente',u.nombre_completo,'telefono',u.telefono,'medicoId',m.id,'medico',um.nombre_completo,'inicio',c.inicio,'fin',c.fin,'estado',c.estado,'motivo',c.motivo,
 'llegada',l.llegada,'enConsulta',l.en_consulta,'version',md5(concat_ws(':',c.id,c.inicio,c.fin,c.estado,c.actualizado_en))) order by c.inicio,c.id)
 from citas c join perfiles_pacientes p on p.id=c.paciente_id join usuarios u on u.id=p.usuario_id join perfiles_medicos m on m.id=c.medico_id join usuarios um on um.id=m.usuario_id
 left join recepcion_llegadas l on l.cita_id=c.id and l.inicio_cita=c.inicio where c.inicio>=v_desde and c.inicio<v_hasta),'[]'::jsonb),
 'medicos',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'nombre',u.nombre_completo,'especialidad',m.especialidad,'bloques',coalesce(a.bloques,'[]'::jsonb),'descansos',coalesce((select jsonb_agg(jsonb_build_object('fecha',d->>'fecha','inicio',d->>'inicio','fin',d->>'fin')) from jsonb_array_elements(coalesce(a.descansos,'[]'::jsonb)) d),'[]'::jsonb)) order by u.nombre_completo) from perfiles_medicos m join usuarios u on u.id=m.usuario_id left join configuracion_agenda a on a.medico_id=m.id where m.esta_activo and u.esta_activo),'[]'::jsonb));
end $$;

create function public.clinica_recepcion_estado(p_cita bigint) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare c citas;
begin
 perform clinica_requerir_sesion();
 select * into c from citas where id=p_cita;
 if c.id is null or clinica_rol() not in('admin','recepcionista','medico','enfermero') or clinica_rol() is null
  or clinica_rol()='medico' and (c.medico_id is distinct from clinica_medico() or not clinica_paciente(c.paciente_id))
  or clinica_rol()='enfermero' and not clinica_paciente(c.paciente_id) then raise exception 'Sin acceso a esta cita' using errcode='42501'; end if;
 return jsonb_build_object('id',c.id,'estado',c.estado,'puedeIniciar',clinica_rol()='medico','version',md5(concat_ws(':',c.id,c.inicio,c.fin,c.estado,c.actualizado_en)),
  'llegada',(select llegada from recepcion_llegadas where cita_id=c.id and inicio_cita=c.inicio),'enConsulta',(select en_consulta from recepcion_llegadas where cita_id=c.id and inicio_cita=c.inicio));
end $$;

create function public.clinica_recepcion_operar(p_cita bigint,p_version text,p_accion text,p_motivo text,p_clave uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare c citas; u usuarios; evento recepcion_eventos; solicitud jsonb; l recepcion_llegadas; destino bigint;
begin
 perform clinica_requerir_sesion();
 select * into u from usuarios where auth_user_id=auth.uid() and esta_activo;
 if u.id is null or u.rol not in('admin','recepcionista','medico') then raise exception 'Sin acceso a recepción' using errcode='42501'; end if;
 if p_accion is null or p_accion not in('llegada','iniciar','confirmar','cancelar','no_asistio') or p_clave is null or length(coalesce(p_motivo,''))>1000 then raise exception 'Solicitud inválida'; end if;
 solicitud:=jsonb_build_object('cita',p_cita,'version',p_version,'accion',p_accion,'motivo',p_motivo);
 perform pg_advisory_xact_lock(37204,0);
 select * into evento from recepcion_eventos where autor=u.id and clave=p_clave;
 if found then
  if evento.solicitud is distinct from solicitud then raise exception 'Esta solicitud ya fue utilizada' using errcode='40001'; end if;
  return jsonb_build_object('ok',true,'mensaje','La acción ya quedó registrada.');
 end if;
 select * into c from citas where id=p_cita for update;
 if not found then raise exception 'Cita no encontrada'; end if;
 if u.rol='medico' and (c.medico_id is distinct from clinica_medico() or not clinica_paciente(c.paciente_id)) then raise exception 'Esta cita pertenece a otro médico' using errcode='42501'; end if;
 if p_version is distinct from md5(concat_ws(':',c.id,c.inicio,c.fin,c.estado,c.actualizado_en)) then raise exception 'La cita cambió. Actualiza la agenda e inténtalo de nuevo' using errcode='40001'; end if;
 if c.estado::text not in('pendiente','confirmada') then raise exception 'Esta cita ya fue resuelta'; end if;
 select * into l from recepcion_llegadas where cita_id=c.id and inicio_cita=c.inicio;
 if p_accion='iniciar' then
  if u.rol<>'medico' then raise exception 'Solo el médico inicia la consulta' using errcode='42501'; end if;
  if l.cita_id is null then raise exception 'Registra primero la llegada del paciente'; end if;
  if l.en_consulta is not null then raise exception 'La consulta ya está en curso'; end if;
  if exists(select 1 from recepcion_llegadas otra join citas cc on cc.id=otra.cita_id and cc.inicio=otra.inicio_cita where cc.medico_id=c.medico_id and cc.id<>c.id and cc.estado in('pendiente','confirmada') and otra.en_consulta is not null) then raise exception 'Finaliza la consulta en curso antes de iniciar otra'; end if;
  update recepcion_llegadas set en_consulta=clock_timestamp(),iniciado_por=u.id where cita_id=c.id;
 elsif p_accion='llegada' then
  if (c.inicio at time zone 'America/Mexico_City')::date<>(clock_timestamp() at time zone 'America/Mexico_City')::date then raise exception 'Solo puedes registrar llegadas de hoy'; end if;
  if l.cita_id is not null then raise exception 'La llegada ya está registrada'; end if;
  insert into recepcion_llegadas(cita_id,inicio_cita,autor,clave) values(c.id,c.inicio,u.id,p_clave)
   on conflict(cita_id) do update set inicio_cita=excluded.inicio_cita,llegada=excluded.llegada,autor=excluded.autor,clave=excluded.clave,en_consulta=null,iniciado_por=null;
  insert into notificaciones(usuario_id,tipo,titulo,mensaje,clave)
   select id,'recepcion','Paciente en sala de espera','Se registró la llegada para la cita #'||c.id||'. Revisa tu agenda.','recepcion:'||p_clave
   from usuarios where esta_activo and (id=(select usuario_id from perfiles_medicos where id=c.medico_id)
    or id in(select e.usuario_id from enfermeria_turnos t join perfiles_enfermeros e on e.id=t.enfermero_id where t.paciente_id=c.paciente_id and not t.cancelado and t.inicio<=clock_timestamp() and t.fin>clock_timestamp() and e.esta_activo)) on conflict do nothing;
 else
  if u.rol not in('admin','recepcionista') then raise exception 'Esta acción corresponde a recepción' using errcode='42501'; end if;
  if l.en_consulta is not null then raise exception 'La consulta ya comenzó. Comunícate con el médico'; end if;
  if p_accion in('cancelar','no_asistio') and length(trim(coalesce(p_motivo,'')))=0 then raise exception 'Indica el motivo'; end if;
  if p_accion='no_asistio' and (c.fin>clock_timestamp() or l.cita_id is not null) then raise exception 'Solo registra inasistencia después del horario y si el paciente no llegó'; end if;
  update citas set estado=(case p_accion when 'confirmar' then 'confirmada' when 'cancelar' then 'cancelada_paciente' else 'no_asistio' end)::estado_cita,
   motivo_cancelacion=case when p_accion='confirmar' then null else trim(p_motivo) end,actualizado_en=clock_timestamp() where id=c.id;
 end if;
 insert into recepcion_eventos(cita_id,autor,accion,motivo,clave,solicitud) values(c.id,u.id,p_accion,nullif(trim(p_motivo),''),p_clave,solicitud);
 return jsonb_build_object('ok',true,'mensaje',case p_accion when 'llegada' then 'Llegada registrada. El equipo fue notificado.' when 'iniciar' then 'Consulta iniciada.' when 'confirmar' then 'Cita confirmada.' when 'cancelar' then 'Cita cancelada.' else 'Inasistencia registrada.' end);
end $$;
revoke all on function clinica_recepcion_proteger() from public,anon,authenticated,service_role;
revoke all on function clinica_recepcion_llegada_enfermeria() from public,anon,authenticated,service_role;
revoke all on function clinica_directorio_recepcion(bigint),clinica_recepcion_panel(date),clinica_recepcion_estado(bigint),clinica_recepcion_operar(bigint,text,text,text,uuid) from public,anon;
grant execute on function clinica_directorio_recepcion(bigint),clinica_recepcion_panel(date),clinica_recepcion_estado(bigint),clinica_recepcion_operar(bigint,text,text,text,uuid) to authenticated;
create or replace function public.clinica_version() returns integer language sql stable as $$ select 30 $$;
notify pgrst,'reload schema';
commit;
